      standaloneQuestions: [
        { id: "PHYCHM_R4_Q_015_01", stem: "用密度鑑別前，第一步應取得？", options: ["只測質量並假設各樣品等體積","同一樣品的質量與體積","只測體積並假設各材料等質量","只依樣品名稱猜測材料"], answerIndex: 1, rationales: ["沒有體積就無法排除尺寸造成的質量差。","同一樣品的 m/V 才能得到密度。","不同材料同體積的質量可不同，缺少質量資料。","名稱可能未知或標示錯誤，不能代替物性量測。"], reviewEvidence: "密度定義為同一樣品的質量除以體積，因此兩項原始量都不可省略。", difficulty: "foundation", cognitiveProcess: ["辨認"] },
        { id: "PHYCHM_R4_Q_015_02", stem: "樣品 54 g、20 cm³，密度最接近參考值 2.70 g/cm³ 的哪項？", options: ["2.70","34","74","0.37"], answerIndex: 0, rationales: ["54÷20＝2.70。","誤用減法。","誤用加法。","顛倒比值。"], reviewEvidence: "樣品密度 2.70 g/cm³。", difficulty: "foundation", cognitiveProcess: ["關係判讀"] },
        { id: "PHYCHM_R4_Q_015_03", stem: "密度比較時，參考表與樣品最好具有哪項共同條件？", options: ["相同量筒讀值","相同樣品質量","相同樣品形狀","相近溫度"], answerIndex: 3, rationales: ["不同樣品不必具有相同體積。","同種均勻材料的密度不要求樣品質量相同。","形狀不同不妨礙以各自 m/V 比較。","溫度會影響體積與密度。"], reviewEvidence: "參考密度與實測密度應在相近溫度比較，避免熱脹冷縮造成系統差異。", difficulty: "foundation", cognitiveProcess: ["單位檢核"] },
        { id: "PHYCHM_R4_Q_015_04", stem: "未知液體密度 0.79 g/mL，候選甲 0.80、乙 1.00、丙 1.26。哪項最穩妥？", options: ["最接近丙","必定是甲且為純物質","在三者中最接近甲","密度無法提供任何線索"], answerIndex: 2, rationales: ["與丙差最大。","仍需誤差與純度證據。","與甲差 0.01 最小。","密度可縮小候選。"], reviewEvidence: "差距甲 0.01、乙 0.21、丙 0.47。", difficulty: "standard", cognitiveProcess: ["資料判讀","應用"] },
        { id: "PHYCHM_R4_Q_015_05", stem: "兩候選密度範圍重疊，樣品值落在重疊區。應如何？", options: ["任選第一個","宣稱兩物質完全相同","把密度改成不重疊","增加其他物性測試"], answerIndex: 3, rationales: ["沒有證據。","範圍重疊不等於身分相同。","不能修改資料。","獨立性質可區分候選。"], reviewEvidence: "密度不能區分時需新證據。", difficulty: "standard", cognitiveProcess: ["條件判斷"] },
        { id: "PHYCHM_R4_Q_015_06", stem: "學生看到 7.8 g/cm³ 就斷言純鐵。錯在哪裡？", options: ["g/cm³ 是體積單位","7.8 不能有小數","鐵沒有密度","未考慮量測誤差、合金與其他相近材料"], answerIndex: 3, rationales: ["這是密度單位。","小數合理。","鐵有密度。","單一近似值不足唯一鑑別。"], reviewEvidence: "7.8 接近鐵但也可能為合金或受誤差影響。", difficulty: "standard", cognitiveProcess: ["錯誤分析"] },
        { id: "PHYCHM_R4_Q_015_07", stem: "哪項第二證據可協助區分鐵與鋁？", options: ["磁鐵吸引情形","再量一次同一樣品的外觀尺寸","只把密度小數位增加","改用更大的兩塊樣品但不測性質"], answerIndex: 0, rationales: ["一般鐵樣品與鋁樣品的磁性表現不同。","尺寸不是區分兩種材料身分的獨立性質。","增加書寫位數不會新增材料證據。","放大樣品仍未提供能區分鐵、鋁的測試結果。"], reviewEvidence: "磁性是不同於密度的可測性質，能為鐵與鋁候選提供獨立區分證據。", difficulty: "standard", cognitiveProcess: ["證據判讀"] },
        { id: "PHYCHM_R4_Q_015_08", stem: "樣品密度 1.05±0.10 g/mL，候選甲 1.00、乙 1.10。能否只靠此值排除其中一個？", options: ["不能，誤差範圍同時涵蓋兩者","能，只留甲","能，兩者都排除","能，只留乙"], answerIndex: 0, rationales: ["0.95–1.15 同時含 1.00、1.10。","乙也在範圍。","兩者皆相容。","甲也在範圍。"], reviewEvidence: "不確定範圍 [0.95,1.15] 包含兩候選。", difficulty: "standard", cognitiveProcess: ["關係應用"] },
        { id: "PHYCHM_R4_Q_015_09", stem: "某樣品有許多封閉氣孔，量得平均密度低於材料表。最合理解釋？", options: ["單位一定錯","密度公式失效","外部體積包含低質量孔隙","氣孔會增加純材料質量，所以平均密度降低"], answerIndex: 2, rationales: ["不必然是單位錯。","公式仍適用整體。","孔隙降低整體 m/V。","氣孔不增加材料。"], reviewEvidence: "封閉氣孔增加外部體積而少增質量。", difficulty: "advanced", cognitiveProcess: ["證據判讀","分析"] },
        { id: "PHYCHM_R4_Q_015_10", stem: "『最接近參考值』與『已證明身分』有何差別？", options: ["前者是候選判斷，後者還需排除誤差與其他候選","最接近一定比證明更強","兩句完全相同","密度表可直接決定純度"], answerIndex: 0, rationales: ["正確區分證據強度。","最接近只是初步。","證據門檻不同。","純度需另證。"], reviewEvidence: "保留鑑別的不確定與替代解釋。", difficulty: "advanced", cognitiveProcess: ["主張評估"] },
        { id: "PHYCHM_R4_Q_015_11", stem: "回收場量到金屬片密度約 2.7 g/cm³，下一步最合理？", options: ["只看大小決定","暫列鋁候選並做導電、磁性或標示查核","改寫成 7.8 g/cm³","立刻宣稱純鋁"], answerIndex: 1, rationales: ["大小不決定材料。","以多證據確認候選。","不得改資料。","單一密度不足。"], reviewEvidence: "2.7 支持鋁候選，後續查核降低誤判。", difficulty: "transfer", cognitiveProcess: ["情境遷移"] },
        { id: "PHYCHM_R4_Q_015_12", stem: "資料表沒有標示參考密度的溫度與來源，應如何使用？", options: ["刪除樣品數據","列為限制並尋找可追溯資料","視為永久精確真值","把所有密度接近的候選都視為同一物質"], answerIndex: 1, rationales: ["樣品數據仍可保留。","缺少條件會限制比較。","來源不明不能視為絕對。","沒有此推論。"], reviewEvidence: "密度受條件影響且資料需可追溯。", difficulty: "transfer", cognitiveProcess: ["限制評估"] },
      ],
